'use strict';

/*
 * My Fit Plan v3.2.3A · Real Motion
 * Cinco demostraciones anatómicas integradas como Blob URLs.
 * No dependen de carpetas externas ni de rutas de GitHub Pages.
 */
const RAW_REAL_MOTION = {"barbell_bench_press":{"videoBase64":"","posterBase64":""},"lat_pulldown":{"videoBase64":"","posterBase64":""},"leg_press":{"videoBase64":"","posterBase64":""},"biceps_curl":{"videoBase64":"","posterBase64":""},"bird_dog":{"videoBase64":"","posterBase64":""}};
const URL_CACHE = new Map();

function base64ToBlobUrl(base64, mime, key) {
  if (!base64) return "";
  if (URL_CACHE.has(key)) return URL_CACHE.get(key);
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) {
    bytes[index] = binary.charCodeAt(index);
  }
  const url = URL.createObjectURL(new Blob([bytes], { type: mime }));
  URL_CACHE.set(key, url);
  return url;
}

export function getRealMotionAsset(id) {
  const item = RAW_REAL_MOTION[id];
  if (!item) return null;
  return {
    video: base64ToBlobUrl(item.videoBase64, "video/mp4", `${id}:video`),
    poster: base64ToBlobUrl(item.posterBase64, "image/jpeg", `${id}:poster`)
  };
}

export const realMotionAssetIds = Object.freeze(Object.keys(RAW_REAL_MOTION));
